      thinkers: [['René Descartes', '1596–1650', 'Mind–body dualism; reflex action; innate ideas', 'Meditations on First Philosophy'], ['Baruch Spinoza', '1632–1677', 'Mind and body as one substance; a theory of emotions', 'Ethics'], ['Gottfried Leibniz', '1646–1716', 'Unconscious perceptions (“petites perceptions”)', 'New Essays on Human Understanding'], ['Immanuel Kant', '1724–1804', 'The mind organises experience with built-in categories like time and space', 'Critique of Pure Reason']],
