      history: [[1796, 'Franz Joseph Gall begins lecturing on “organology” in Vienna'], [1810, 'Gall and Spurzheim publish their large work on the brain'], [1824, 'Flourens’ experiments on animal brains challenge Gall'], [1861, 'Broca’s work on speech gives real evidence for brain localisation']],
      thinkers: [['Franz Joseph Gall', '1758–1828', 'Proposed localisation of mental functions in the brain', 'The Anatomy and Physiology of the Nervous System'], ['Johann Spurzheim', '1776–1832', 'Spread and named phrenology', 'Phrenology'], ['George Combe', '1788–1858', 'Popularised phrenology in Britain', 'The Constitution of Man']],
