      thinkers: [['Wilhelm Wundt', '1832–1920', 'Founded experimental psychology; voluntarism; Völkerpsychologie', 'Principles of Physiological Psychology'], ['Edward Titchener', '1867–1927', 'Named and led structuralism in America', 'A Textbook of Psychology'], ['Oswald Külpe', '1862–1915', 'Würzburg school: found “imageless thought”', 'Outlines of Psychology']],
